import{encodeLink as x,decodeLink as g}from"../../shared/js/avatar-1.0.0.min.js";export const REMIX_VERSION=1;export function encodeCaption(t){return encodeURIComponent(String(t??"")).replace(/%20/g,"+")}export function decodeCaption(t){try{return decodeURIComponent(String(t).replace(/\+/g,"%20"))}catch{return null}}export function encodeMeme(t){const o=t.captions.map(encodeCaption).join("|"),c=t.expressions.map(e=>e||"-").join(",");return`m=${REMIX_VERSION}/${t.template}/${o}/${c}`}export function encodeRemix(t,o=null,{max:c=2e3}={}){const e=t.captions.slice(),i=()=>{const n=encodeMeme({...t,captions:e});return o?`${n}&${x(o)}`:n};let l=i();for(;l.length>c;){let n=-1;if(e.forEach((p,s)=>{p.length&&(n<0||p.length>e[n].length)&&(n=s)}),n<0)break;e[n]=e[n].slice(0,-1),l=i()}return l}export function decodeRemix(t,o,{max:c=2e3,normalize:e}={}){if(typeof t!="string"||t.length>c)return null;const i=t.replace(/^#/,"").split("&").find(r=>r.startsWith("m="));if(!i)return null;const[l,n,p="",s=""]=i.slice(2).split("/");if(l!==String(REMIX_VERSION)||!o.templates.some(r=>r.id===n))return null;const a=p===""?[]:p.split("|").map(decodeCaption),d=a.some(r=>r===null)?[]:a,f=s===""?[]:s.split(",").map(r=>r==="-"?null:r),m=e({template:n,captions:d,expressions:f},o),u=t.replace(/^#/,"").split("&").find(r=>r.startsWith("a="));return{meme:m,avatar:u?g(u):null}}export function remixUrl(t,o,c,e){let i;try{i=new URL(".",c).href}catch{i=String(c||"")}return`${i}#${encodeRemix(t,o,e)}`}
